# Slack allowed above a room's minimum when the caller gives no maximum.
DEFAULT_UB_FACTOR = 5
# Floor on that slack when the caller DOES give a maximum. In a gapless
# rectangular tiling a column of small rooms must still stack to the same total
# as a column of large ones, so a hard per-room ceiling makes almost every
# topology infeasible and the whole catalogue collapses. The caller's ceiling is
# therefore widened here and enforced exactly later, where the leftover area is
# distributed (api._fill_gaps), which is where the real blow-up happened.
SOLVER_UB_SLACK = float(os.environ.get("GPLAN_SOLVER_UB_SLACK", "2.5"))


def upper_bound(supplied, low, exact=False, strict=False):
    """Upper bound for one room axis in the longest-path solve.

    Honours a caller-supplied maximum, widened to at least SOLVER_UB_SLACK x the
    minimum so the topology search keeps its freedom, and never looser than the
    historical DEFAULT_UB_FACTOR x the minimum. Falls back to the historical
    bound when no maximum is given, when it is the 99999 "open" sentinel, or
    when it is unusable.
    """
    low = float(low)
    # A fixed room is a hard obstacle in the dissection, not a normal room
    # ceiling.  Normal ceilings deliberately get SOLVER_UB_SLACK so topology
    # search does not collapse; doing that to a stair/lift silently turns an
    # equality into a 2.5x band before any later validator can help.
    if exact:
        return low
    open_ub = DEFAULT_UB_FACTOR * low
    if supplied is None:
        return open_ub
    try:
        value = float(supplied)
    except (TypeError, ValueError):
        return open_ub
    if value <= 0 or value >= 99999:
        return open_ub
    if strict:
        return value
    return min(open_ub, max(value, SOLVER_UB_SLACK * low))


# populates the structures with the user constraints to be further used in the longest path caculations
def input_constraints():
    global lb_len, ub_len, lb_width, ub_width

    # print("For each room, please enter the lower and upper bounds for length and width")

    lb_len.append(-1)
    ub_len.append(-1)
    lb_width.append(-1)
    ub_width.append(-1)

    for i in range(1, rooms + 1):
        node = data['nodes'][i-1]

        low_len = float(node['min_height'])
        up_len = upper_bound(node.get('max_height'), low_len,
                             exact=bool(node.get('is_fixed')), strict=bool(data.get('strict_room_bounds')))

        low_width = float(node['min_width'])
        up_width = upper_bound(node.get('max_width'), low_width,
                               exact=bool(node.get('is_fixed')), strict=bool(data.get('strict_room_bounds')))

        lb_len.append(low_len)
        ub_len.append(up_len)
        lb_width.append(low_width)
        ub_width.append(up_width)


# wrapper function to take the input data
def input_data():
    global rooms, edgesX, edgesY,adj

    # print("Please enter the number of rooms:")
    rooms = len(data['nodes'])

    edgesX = [[POS_INF for _ in range(2 * (rooms + 1))] for _ in range(2 * (rooms + 1))]
    edgesY = [[POS_INF for _ in range(2 * (rooms + 1))] for _ in range(2 * (rooms + 1))]

    tblr_rooms()
    
    adj.clear()
    adj = defaultdict(list)
    input_constraints()
    input_adjacency()


#  adding necessary edges pertaining to the adjacency and constraints to the constraint graphs
def construct_constraintgraphX(small_positive = 2):
    global edgesX, edgesY, edges_setx, edges_sety

    # Add limiter of plot width if provided
    if plot_width > 0:
        edgesX[2 * rooms + 1][0] = -1 * plot_width
        edges_setx.append((2 * rooms + 1, 0)) 

    # Add edges for widths of each single room - the user constraints
    for i in range(1, rooms + 1):
        left_wall = 2 * i - 1
        right_wall = 2 * i
        edgesX[left_wall][right_wall] = lb_width[i]
        edgesX[right_wall][left_wall] = -1 * ub_width[i]
        edges_setx.append((left_wall, right_wall))
        edges_setx.append((right_wall, left_wall))

    # Precompute edge color lookup: (source, target) -> color (covers both directions)
    edge_color_map = {}
    for e in data['edges']:
        edge_color_map[(e['source'], e['target'])] = e['color']
        edge_color_map[(e['target'], e['source'])] = e['color']

    # Add edges for adjacencies
    for i in range(1, rooms + 1):
        left_wall_i = 2 * i - 1
        right_wall_i = 2 * i
        top_wall_i = 2 * i - 1
        bottom_wall_i = 2 * i

        for x in adj[i]:
            color = edge_color_map.get((x, i)) or edge_color_map.get((i, x))
            if color == 'red':
                small_positive = adjacency_overlap_floor
            elif color == 'black':
                small_positive = DOOR_OVERLAP_FLOOR if data.get('strict_room_bounds') else 2


            left_wall_x = 2 * x - 1
            right_wall_x = 2 * x
            top_wall_x = 2 * x - 1
            bottom_wall_x = 2 * x

            type_val = adj_type[(i, x)]
            if type_val == 1:
                # i is to the right
                edgesX[right_wall_x][left_wall_i] = 0
                edgesX[left_wall_i][right_wall_x] = 0
                edges_setx.append((right_wall_x, left_wall_i))
                edges_setx.append((left_wall_i, right_wall_x))
                
                # Constraints for top walls
                edgesY[top_wall_i][bottom_wall_x] = NEG_INF
                edgesY[bottom_wall_x][top_wall_i] = small_positive
                edges_sety.append((top_wall_i, bottom_wall_x))
                edges_sety.append((bottom_wall_x, top_wall_i))

                edgesY[top_wall_x][bottom_wall_i] = NEG_INF
                edgesY[bottom_wall_i][top_wall_x] = small_positive
                edges_sety.append((top_wall_x, bottom_wall_i))
                edges_sety.append((bottom_wall_i, top_wall_x))

            elif type_val == 2:
                # i is to the left
                edgesX[left_wall_x][right_wall_i] = 0
                edgesX[right_wall_i][left_wall_x] = 0
                edges_setx.append((left_wall_x, right_wall_i))
                edges_setx.append((right_wall_i, left_wall_x))
                
                # Constraints for top walls
                edgesY[top_wall_i][bottom_wall_x] = NEG_INF
                edgesY[bottom_wall_x][top_wall_i] = small_positive
                edges_sety.append((top_wall_i, bottom_wall_x))
                edges_sety.append((bottom_wall_x, top_wall_i))

                edgesY[top_wall_x][bottom_wall_i] = NEG_INF
                edgesY[bottom_wall_i][top_wall_x] = small_positive
                edges_sety.append((top_wall_x, bottom_wall_i))
                edges_sety.append((bottom_wall_i, top_wall_x))


