#for computing range of tolerance of each node
def compute_rot(small_positive = 2):
    for i in range(2*rooms):
        rotx1.append(0)#rotx1 represents lower bound of each wall
        rotx2.append(placementx[2*rooms+1])
        roty1.append(0)#represents lower bound of each wall
        roty2.append(placementy[2*rooms+1])

    for i in range(1,rooms+1):
        rotx2[2*i-2]=min(rotx2[2*i-2],placementx[2*i]-data['nodes'][i-1]['min_width'])
        rotx1[2*i-1]=max(rotx1[2*i-1],placementx[2*i-1]+data['nodes'][i-1]['min_width'])
        roty1[2*i-2]=max(roty1[2*i-2],placementy[2*i]+data['nodes'][i-1]['min_height'])
        roty2[2*i-1]=min(roty2[2*i-1],placementy[2*i-1]-data['nodes'][i-1]['min_height'])
    
    #print("debug",roty2[5])
    for i in range(1,rooms+1):
        for x in adj[i]:
            type_val = adj_type[(i, x)]
            if type_val==1:#ith room is on right
                b=data['nodes'][x-1]['min_width']+placementx[2*x-1]
                rotx1[2*i-2]=max(rotx1[2*i-2],b)

            elif type_val==2:#ith room is on left
                a=placementx[2*x]-data['nodes'][x-1]['min_width']
                rotx2[2*i-1]=min(rotx2[2*i-1],a)

            elif type_val==3:#ith room is in bottom
                a=placementy[2*x-1]-data['nodes'][x-1]['min_height']
                roty2[2*i-2]=min(roty2[2*i-2],a)

            elif type_val==4:#ith room is at top
                a=placementy[2*x]+data['nodes'][x-1]['min_height']
                roty1[2*i-1]=max(roty1[2*i-1],a)   
    #print("debug",roty2[5])
    #print("Adjacency list",adj[3])
    for i in range(1,rooms+1):#to handle the small positive 

        for x in adj[i]:
             for j in range(len(data['edges'])):
                if (data['edges'][j]['source'] == x and data['edges'][j]['target'] == i) or (data['edges'][j]['source'] == i and data['edges'][j]['target'] == x) :
                    if(data ['edges'][j]['color'] == 'red') :
                        small_positive = 0.1
                    elif(data ['edges'][j]['color'] == 'black'):
                        small_positive = 2
             #print("Change to be noted",small_positive)
             type_val = adj_type[(i, x)]
             if type_val==1 or type_val==2:
                 a=placementy[2*x]+small_positive
                 b=placementy[2*x-1]-small_positive
                 if roty1[2*i-2]<a:
                    roty1[2*i-2]=a
                 if roty2[2*i-1]>b:
                    #print("small positive",small_positive)
                    #print("change in rot",b,i,x)
                    roty2[2*i-1]=b 
             if type_val==3 or type_val==4:
                 a=placementx[2*x-1]+small_positive
                 b=placementx[2*x]-small_positive
                 if rotx1[2*i-1]<a:
                    rotx1[2*i-1]=a
                 if rotx2[2*i-2]>b:
                    rotx2[2*i-2]=b 
    #print("debug",roty2[5])
    for i in range(1,rooms+1):#to make sure that same walls have same range of tolerance
        for x in adj[i]:
            type_val=adj_type[(i,x)]
            if type_val==1:
                a=max(rotx1[2*i-2],rotx1[2*x-1])
                b=min(rotx2[2*i-2],rotx2[2*x-1])
                rotx1[2*i-2]=a
                rotx1[2*x-1]=a
                rotx2[2*i-2]=b
                rotx2[2*x-1]=b     
            elif type_val==2:
                a=max(rotx1[2*i-1],rotx1[2*x-2])
                b=min(rotx2[2*i-1],rotx2[2*x-2])
                rotx1[2*i-1]=a
                rotx1[2*x-2]=a
                rotx2[2*i-1]=b
                rotx2[2*x-2]=b                           
            elif type_val==3:
                a=max(roty1[2*i-2],roty1[2*x-1])
                b=min(roty2[2*i-2],roty2[2*x-1])
                roty1[2*i-2]=a
                roty1[2*x-1]=a
                roty2[2*i-2]=b
                roty2[2*x-1]=b 
            elif type_val==4:
                a=max(roty1[2*i-1],roty1[2*x-2])
                b=min(roty2[2*i-1],roty2[2*x-2])
                roty1[2*i-1]=a
                roty1[2*x-2]=a
                roty2[2*i-1]=b
                roty2[2*x-2]=b      
    #print("debug",roty2[5])    
                


                

# function for printing range of tolerance
def print_rot():
    print("Range of tolerance in x direction")
    for i in range (2*rooms):
        print(i+1,rotx1[i],rotx2[i])
    print("Range of tolerance in y direction")  
    for i in range (2*rooms):
        print(i+1,roty1[i],roty2[i])

# debugging function
def print_input():
    print(adj_type)
    print(lb_len)
    print(ub_len)
    print(lb_width)
    print(ub_width)

#updating placement of west and south boundary rooms based on range of tolerance to minimize area
def edit_placements():
    for i in range(len(data['boundary_rooms']['west'])):
        j = data['boundary_rooms']['west'][i]
        if rotx2[2*j-2] > placementx[2*j-1]:
            placementx[2*j-1] = rotx2[2*j-2]
            # print('changing x position of wall', j*2-1, 'to ', placementx[2*j-1])
    
    for i in range(len(data['boundary_rooms']['south'])):
        j = data['boundary_rooms']['south'][i]
        if roty2[2*j-1] > placementy[2*j]:
            placementy[2*j] = roty2[2*j-1]
            # print('changing y position of wall ', j*2, 'to ', placementy[2*j])
    
    
# the final file to be given to gplan to show in UI
def return_output():
    global placementx,placementy,data
    out_data={'nodes':[]}
    for i in range(rooms):
        dic={}
        dic.update({'id':data['nodes'][i]['id']})
        if 'label' in data['nodes'][i]:
            dic.update({'label':data['nodes'][i]['label']})
        dic.update({'room_x':float(round(placementx[2*i+1],4))})
        dic.update({'room_y':float(round(placementy[2*i+2],4))})
        dic.update({'width':float(round(placementx[2*i+2],4)-round(placementx[2*i+1],4))})
        dic.update({'height':float(round(placementy[2*i+1],4)-round(placementy[2*i+2],4))})
        out_data['nodes'].append(dic)
    # print(out_data)

    return out_data

 

def reinitialize():
    global rooms,num_sx,num_tx,num_sy,num_ty,sx_adj,sy_adj,adjacent_pairs,adj,adj_type,edgesX,edgesY,edges_setx,edges_sety,lb_len,ub_len,lb_width,ub_width,placementx,placementy,tx_adj,ty_adj,plot_width,plot_height,rotx1,rotx2,roty1,roty2
    rooms = 0
    num_sx, num_tx, num_sy, num_ty = 0, 0, 0, 0
    sx_adj = []
    sy_adj = []
    tx_adj=[]
    ty_adj=[]

    adjacent_pairs = 0
    adj = defaultdict(list)  # contains the adjacency of all the rooms
    adj_type = {}

    edgesX = []
    edgesY = []
    edges_setx = []
    edges_sety = []

    lb_len = []
    ub_len = []
    lb_width = []
    ub_width = []
    plot_width = 0
    plot_height = 0

    placementx = []
    placementy = []

    rotx1=[]
    rotx2=[]
    roty1=[]
    roty2=[]

    irreg_nodes_map.clear()
    door_connectivity_edges.clear()

    global adjacency_overlap_floor
    adjacency_overlap_floor = DOOR_OVERLAP_FLOOR


# main wrapper
def main(input, plot_width, plot_height, overlap_floor=None):
    """`overlap_floor` overrides the briefed-adjacency shared-wall minimum for
    THIS solve (feet). None = DOOR_OVERLAP_FLOOR. solve_min_dim passes the
    legacy 2.0 as a relaxation rung when the door-width floor makes a topology
    infeasible."""
    global data, irreg_nodes_map
    reinitialize()
    if overlap_floor is not None:
        globals()['adjacency_overlap_floor'] = float(overlap_floor)
# <<<<<<< main
    data = input

    # Store the all dummy nodes as the value of the irregular rooms they are adjacent to
    if 'mergednodes' in data and 'irreg_nodes1' in data and 'irreg_nodes2' in data:
        for i in range(0, len(data['mergednodes'])):
            irreg_nodes_map[(data['irreg_nodes1'][i], data['irreg_nodes2'][i])] = data['mergednodes'][i]
    
    # If dummy nodes exist, remove the adjacency between irregular rooms as they are now separated by dummy nodes
    if 'dummy_node_adj' in data:
        for a in data['edges']:

            # Add the edges with door connectivity to the door_connectivity_edges set
            if a['color'] == 'black':
                continue

            # If there is door connectivity between irregular nodes separated by a dummy node, add a door connectivity between the dummy node and irregular node instead
            elif (a['source'], a['target']) in irreg_nodes_map:
                door_connectivity_edges.add((irreg_nodes_map[(a['source'], a['target'])], a['target']))
            elif (a['target'], a['source']) in irreg_nodes_map:
                door_connectivity_edges.add((irreg_nodes_map[(a['target'], a['source'])], a['source']))
            else:
                door_connectivity_edges.add((a['source'], a['target']))
        data['edges'].clear()

        # Update modified edge data
        for a in data['dummy_node_adj']:
            color = 'black'
            if ((a[0], a[1]) in door_connectivity_edges or (a[1], a[0]) in door_connectivity_edges):
                color = 'red'
            data['edges'].append({'source':a[0] + 1, 'target':a[1] + 1, 'color':color})
    else:
        for a in data['edges']:
            a['source']=a['source']+1
            a['target']=a['target']+1
# =======
#     f = open(file_path)
#     data = json.load(f)
#     # print(data)
#     # print(data['edges'][0])
#     for a in data['edges']:
#         a['source']=a['source']+1
#         a['target']=a['target']+1
# >>>>>>> Door_connectivity_cleanup
    for i in range(len(data['boundary_rooms']['north'])):
        data['boundary_rooms']['north'][i]= data['boundary_rooms']['north'][i]+1
    for i in range(len(data['boundary_rooms']['south'])):
        data['boundary_rooms']['south'][i]= data['boundary_rooms']['south'][i]+1
    for i in range(len(data['boundary_rooms']['east'])):
        data['boundary_rooms']['east'][i]= data['boundary_rooms']['east'][i]+1
    for i in range(len(data['boundary_rooms']['west'])):
        data['boundary_rooms']['west'][i]= data['boundary_rooms']['west'][i]+1
    globals()['plot_width'] = plot_width
    globals()['plot_height'] = plot_height
        
    input_data()  # Take all the necessary inputs
    # print_input()

    required_overlap = DOOR_OVERLAP_FLOOR if data.get('strict_room_bounds') else 2
    construct_constraintgraphX(small_positive=required_overlap)
    construct_constraintgraphY(small_positive=required_overlap)
    # print_edges()  # Print edges for X and Y constraints
    if not compute_placement():  # Compute placements using longest path algorithm and return false if no legal placement found
        # print_placements()
        return [False, None]
    # print_placements()  # Print computed placements
    if not data.get('strict_room_bounds'):
        # Legacy boundary compaction uses softer overlap tolerances and can
        # invalidate the hard constraints just solved above.
        compute_rot()
        edit_placements()
    out_data = return_output()
    return [True, out_data]

# Main execution
